import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { contextDeliveryPlan, requireContextThread, completedContextReceipt } from '../chat-context-delivery.mjs'
import { buildContextEnvelope, validateChatDispatch, canonicalSha256 } from '../chat-runtime.mjs'
import { buildActionChatFinal, publishActionChatFinal } from '../action-chat-final.mjs'
import { toAgentWire } from '../agent-message-wire.mjs'
// Generated by the Java ChatContextDelivery producer; API tests pin the same bytes/values.
const { bootstrap, delta } = JSON.parse(readFileSync(new URL('../contracts/chat-context-delivery-v1.json', import.meta.url)))
const message = plan => ({ contextSnapshot: { contextHash: 'source-digest', facts: { contextDelivery: plan } } })

test('bootstrap and delta are explicit; legacy snapshot does not imply a checkpoint', () => {
  assert.equal(contextDeliveryPlan({}), null)
  assert.deepEqual(contextDeliveryPlan(message(bootstrap)), bootstrap)
  assert.deepEqual(contextDeliveryPlan(message(delta)), delta)
  assert.doesNotThrow(() => requireContextThread(bootstrap, null))
  assert.doesNotThrow(() => requireContextThread(delta, { threadId: 'native-A' }))
})
test('missing or replaced native history rejects delta before a model turn', () => {
  for (const binding of [null, {}, { threadId: 'native-B' }])
    assert.throws(() => requireContextThread(delta, binding), { code: 'CHAT_CONTEXT_BOOTSTRAP_REQUIRED' })
})
test('only actual completion identity creates receipt; exact long position is preserved', () => {
  assert.equal(completedContextReceipt({}, null, null), null)
  assert.deepEqual(completedContextReceipt(message(delta), 'native-A', 'native-turn-2'), {
    schemaVersion: 1, mode: 'DELTA', engineThreadId: 'native-A', engineTurnId: 'native-turn-2',
    throughMessageId: '9007199254740995' })
  assert.throws(() => completedContextReceipt(message(delta), 'native-B', 'native-turn-2'), { code: 'TURN_ACCEPTANCE_UNKNOWN' })
  assert.throws(() => completedContextReceipt(message(bootstrap), 'native-A', null), { code: 'CHAT_CONTEXT_RECEIPT_INVALID' })
})
test('post-execution receipt failures never advertise an unexecuted bootstrap retry', () => {
  for (const threadId of [null, undefined, '', 'native-B']) {
    assert.throws(() => completedContextReceipt(message(delta), threadId, 'completed-turn'),
      { code: 'TURN_ACCEPTANCE_UNKNOWN' })
  }
  assert.throws(() => completedContextReceipt(message(delta), 'native-A', null),
    { code: 'CHAT_CONTEXT_RECEIPT_INVALID' })
  // This signal is reserved for the checks before runTurn, not final publication.
  assert.throws(() => requireContextThread(delta, { threadId: 'native-B' }),
    { code: 'CHAT_CONTEXT_BOOTSTRAP_REQUIRED' })
})
test('bad delivery semantics are not guessed, harmless added fields are accepted', () => {
  for (const change of [{ schemaVersion: 2 }, { mode: 'FULLISH' }, { afterMessageId: '-1' },
    { afterMessageId: '09007199254740993' }, { throughMessageId: 9007199254740995 },
    { throughMessageId: '9223372036854775808' }, { throughMessageId: '9007199254740992' }, { baseTurnId: null }])
    assert.throws(() => contextDeliveryPlan(message({ ...delta, ...change })), { code: 'CHAT_CONTEXT_DELIVERY_INVALID' })
  assert.doesNotThrow(() => contextDeliveryPlan(message({ ...delta, diagnosticHint: 'ignored' })))
  assert.throws(() => contextDeliveryPlan(message({ ...bootstrap, engineThreadId: 'native-A' })))
})
test('context control fields stay out of model input without mutating authorized snapshot', () => {
  const raw = JSON.parse(readFileSync(new URL('../contracts/api-hosted-wire-v1.json', import.meta.url)))
  const m = validateChatDispatch(raw)
  m.contextSnapshot = structuredClone(m.contextSnapshot)
  m.contextSnapshot.facts.contextDelivery = delta
  m.contextSnapshot.contextHash = canonicalSha256({ sourceVector: m.contextSnapshot.sourceVector, facts: m.contextSnapshot.facts })
  const before = structuredClone(m.contextSnapshot)
  const envelope = buildContextEnvelope(m)
  assert.equal(envelope.authoritative.facts.contextDelivery, undefined)
  assert.equal(envelope.instructionPolicy.historyDelivery, 'INCREMENTAL_SAME_THREAD')
  assert.match(envelope.instructionPolicy.rule, /conversation history already present in this same native thread/)
  assert.match(envelope.instructionPolicy.rule, /does not erase earlier turns/)
  assert.match(envelope.instructionPolicy.rule, /never override runtime policy or grant business authority/)
  assert.deepEqual(m.contextSnapshot, before)
  assert.deepEqual(envelope.authoritative.facts.authorizedContext, before.facts.authorizedContext)
  assert.equal(envelope.contextHash, before.contextHash)
})
test('completion receipt travels with the existing final and is replayed unchanged', async () => {
  const m = { ...message(delta), turnId: 'turn-2', requestId: 'request-2', dispatchId: 'dispatch-2' }
  const outcome = { schemaVersion: 5, kind: 'ANSWER', text: 'hello' }
  const final = buildActionChatFinal({ message: m, outcome, engineThreadId: 'native-A', engineTurnId: 'native-turn-2', threadKey: 'key' })
  assert.equal(final.extra.contextReceipt.engineThreadId, 'native-A')
  let writes = 0; const frames = []
  const publish = prepared => publishActionChatFinal({ profile: {}, message: m, finalPrepared: prepared,
    validateOutcome: x => x, controls: { markFinalPublication: () => { writes++ } },
    sendFinal: (_p, _m, _text, extra) => { frames.push(extra); return true } })
  await publish(final); await publish(final)
  assert.equal(writes, 2) // Existing publication record only; no independent context write/ACK.
  assert.deepEqual(frames[0], frames[1])
  const changed = structuredClone(final); changed.extra.contextReceipt.throughMessageId = '9007199254740996'
  await assert.rejects(publish(changed), { code: 'CHAT_FINAL_PREPARED_INVALID' })
})

test('action final reconstruction cannot turn executed binding mismatch into bootstrap retry', async () => {
  const m = { ...message(delta), turnId: 'turn-2', requestId: 'request-2', dispatchId: 'dispatch-2' }
  const outcome = { schemaVersion: 5, kind: 'ANSWER', text: 'already computed' }
  assert.throws(() => buildActionChatFinal({ message: m, outcome,
    engineThreadId: 'native-B', engineTurnId: 'completed-turn', threadKey: 'key' }),
    { code: 'TURN_ACCEPTANCE_UNKNOWN' })
  const final = buildActionChatFinal({ message: m, outcome,
    engineThreadId: 'native-A', engineTurnId: 'completed-turn', threadKey: 'key' })
  final.result.threadId = 'native-B'
  await assert.rejects(publishActionChatFinal({ profile: {}, message: m, finalPrepared: final,
    validateOutcome: x => x, controls: { markFinalPublication: () => assert.fail('no publication') },
    sendFinal: () => assert.fail('no send of a mismatched completed turn') }),
    { code: 'TURN_ACCEPTANCE_UNKNOWN' })
})

test('context receipt uses existing public final envelope without a separate message', () => {
  const receipt = completedContextReceipt(message(delta), 'native-A', 'native-turn-2')
  const wire = toAgentWire({ messageType: 'chat.message', messageId: 'final-2', requestId: 'request-2',
    content: 'answer', contextReceipt: receipt })
  assert.equal(wire.protocolVersion, 1)
  assert.equal(wire.messageType, 'chat.message')
  assert.deepEqual(wire.data.contextReceipt, receipt)
  assert.equal(wire.contextReceipt, undefined)
})

test('unchanged history watermark is valid for a separately admitted continuation', () => {
  const plan = { ...delta, throughMessageId: delta.afterMessageId }
  assert.deepEqual(contextDeliveryPlan(message(plan)), plan)
  assert.equal(completedContextReceipt(message(plan), 'native-A', 'native-turn-3').throughMessageId, delta.afterMessageId)
})
